"""The welcome screen, which Falcon starts on: the pipelines under ~/falcon listed, one opened in
the designer by a click, a new one made from a name, and the way back from the designer."""
import tempfile
import time
from pathlib import Path

from designer_driver import Designer

HEADER = """// falcon-pipeline-header-start
// Name: {name}
// Description: {description}
// Generated by Falcon: v26.11.21
// falcon-pipeline-header-end
"""

EMPTY_PIPELINE = """#include "core/engine.cpp"

int main(int argument_count, char** arguments) {
    return run_on_cores(argument_count, arguments, {
    });
}
"""


def write_pipeline(home, folder, name, description="", body=EMPTY_PIPELINE):
    directory = Path(home) / "falcon" / folder
    directory.mkdir(parents=True)
    (directory / "pipeline.cpp").write_text(
        HEADER.format(name=name, description=description) + body)
    return directory


def welcome_screen(home):
    return Designer(home=home, starts_on_welcome_screen=True)


def state_once_searched(designer):
    """The welcome screen's state once it has looked for the pipelines, which it does beside the
    UI's thread."""
    end = time.monotonic() + 5
    while time.monotonic() < end:
        designer.frames(1)
        state = designer.state()
        if state["screen"] == "explorer" and state["has_searched"]:
            return state
        time.sleep(0.02)
    raise AssertionError("the welcome screen never listed the pipelines")


def file_with(path, part):
    """The file's text once it holds this part: files are written beside the UI's thread."""
    end = time.monotonic() + 5
    while time.monotonic() < end:
        if path.exists() and part in path.read_text():
            return path.read_text()
        time.sleep(0.02)
    raise AssertionError(f"{path} never held {part}")


def test_falcon_starts_on_the_welcome_screen_which_lists_no_pipeline_at_first():
    with tempfile.TemporaryDirectory() as home:
        with welcome_screen(home) as designer:
            state = state_once_searched(designer)
            assert state["pipelines"] == []
            assert designer.has_target("explorer/new_name")
            assert not designer.has_target("top_bar/compile")


def test_pipelines_are_listed_by_their_folders_with_name_and_description():
    with tempfile.TemporaryDirectory() as home:
        write_pipeline(home, "spike_sorting", "Spike sorting", "Sorts spikes on 64 channels.")
        write_pipeline(home, "memory", "Memory impairment")
        # No pipeline's: a folder without a pipeline.cpp, one whose file lacks the header block,
        # and the app's own folder.
        (Path(home) / "falcon" / "notes").mkdir()
        (Path(home) / "falcon" / "by_hand").mkdir()
        (Path(home) / "falcon" / "by_hand" / "pipeline.cpp").write_text(EMPTY_PIPELINE)
        write_pipeline(home, ".config", "Hidden")
        with welcome_screen(home) as designer:
            state = state_once_searched(designer)
            assert state["pipelines"] == [
                {"folder": "memory", "name": "Memory impairment", "description": "",
                 "problem": ""},
                {"folder": "spike_sorting", "name": "Spike sorting",
                 "description": "Sorts spikes on 64 channels.", "problem": ""},
            ]
            assert (designer.target("explorer/pipeline/memory").bottom <=
                    designer.target("explorer/pipeline/spike_sorting").top)


def test_click_on_a_pipeline_opens_it_in_the_designer():
    with tempfile.TemporaryDirectory() as home:
        with Designer(home=home) as designer:
            trigger = designer.add_processor("Trigger", core=0)
            file_with(Path(home) / "falcon" / "prototype_folder" / "pipeline.cpp", "Trigger<")
        write_pipeline(home, "another", "Another pipeline")
        with welcome_screen(home) as designer:
            state_once_searched(designer)
            designer.click("explorer/pipeline/prototype_folder")
            designer.frames(3)
            assert designer.state()["screen"] == "designer"
            assert set(designer.processors()) == {trigger}
            # A pipeline without a name is called by its folder.
            assert designer.has_target("top_bar/pipeline_name")


def test_new_pipeline_is_made_from_its_name_and_opened():
    with tempfile.TemporaryDirectory() as home:
        with welcome_screen(home) as designer:
            state_once_searched(designer)
            designer.click("explorer/new_name")
            designer.type_text("Memory Impairment, Day 2")
            designer.key("Enter")
            designer.frames(3)
            assert designer.state()["screen"] == "designer"
            assert designer.processors() == {}
            # Its folder is named after it, and its file is there before anything is done.
            file = Path(home) / "falcon" / "memory_impairment_day_2" / "pipeline.cpp"
            assert "// Name: Memory Impairment, Day 2\n" in file_with(file, "// Name:")
        with welcome_screen(home) as designer:
            state = state_once_searched(designer)
            assert [pipeline["folder"] for pipeline in state["pipelines"]] == [
                "memory_impairment_day_2"]
            assert state["pipelines"][0]["name"] == "Memory Impairment, Day 2"


def test_new_pipeline_is_refused_without_a_name_or_where_its_folder_is_taken():
    with tempfile.TemporaryDirectory() as home:
        write_pipeline(home, "memory", "Memory")
        (Path(home) / "falcon" / "notes").mkdir()
        with welcome_screen(home) as designer:
            state_once_searched(designer)
            designer.click("explorer/create")
            assert designer.state()["new_pipeline_problem"] == "A pipeline needs a name."
            for name, problem in (("memory", "The folder memory is there already."),
                                  ("Notes!", "The folder notes is there already."),
                                  ("?!", "A pipeline's name needs a letter or a digit.")):
                designer.click("explorer/new_name")
                designer.key("Ctrl+A")
                designer.type_text(name)
                designer.click("explorer/create")
                assert designer.state()["screen"] == "explorer"
                assert designer.state()["new_pipeline_problem"] == problem
            assert not (Path(home) / "falcon" / "notes" / "pipeline.cpp").exists()


def test_pipeline_that_cannot_be_read_says_why_and_is_not_opened():
    with tempfile.TemporaryDirectory() as home:
        write_pipeline(home, "broken", "Broken one", body="this is no pipeline\n")
        with welcome_screen(home) as designer:
            state = state_once_searched(designer)
            assert state["pipelines"][0]["name"] == "Broken one"
            assert state["pipelines"][0]["problem"] != ""
            assert designer.target("explorer/pipeline/broken").note == (
                state["pipelines"][0]["problem"])
            designer.click("explorer/pipeline/broken")
            designer.frames(3)
            assert designer.state()["screen"] == "explorer"


def test_designer_leads_back_to_the_welcome_screen_which_lists_what_was_made():
    with tempfile.TemporaryDirectory() as home:
        with welcome_screen(home) as designer:
            state_once_searched(designer)
            designer.click("explorer/new_name")
            designer.type_text("First")
            designer.click("explorer/create")
            designer.frames(3)
            trigger = designer.add_processor("Trigger", core=0)
            designer.click("top_bar/pipelines")
            state = state_once_searched(designer)
            assert [pipeline["name"] for pipeline in state["pipelines"]] == ["First"]

            # What was done in the designer is there when the pipeline is opened again.
            designer.click("explorer/pipeline/first")
            designer.frames(3)
            assert set(designer.processors()) == {trigger}
